package files

import (
	_ "embed"
	"fmt"
	sdk "github.com/MichaelKinsy/PiG/extensions/sdk"
	"github.com/MichaelKinsy/pigpen/oh-my-pig/internal/hashline"
	"github.com/MichaelKinsy/pigpen/oh-my-pig/internal/intent"
	"github.com/MichaelKinsy/pigpen/oh-my-pig/internal/lifecycle"
	"github.com/MichaelKinsy/pigpen/oh-my-pig/internal/schemaorder"
	"math"
	"strings"
)

//go:embed read.md
var readDescription string

//go:embed write.md
var writeDescription string

//go:embed edit.md
var editDescription string

// Setting reads a session setting by omp setting key (e.g. "edit.blockAutoGenerated",
// "edit.enforceSeenLines", "read.defaultLimit", "tools.artifactSpillThreshold",
// "tools.outputMaxColumns"). Wired by the integrator to `settings.Any`; nil uses
// omp's defaults.
var Setting func(ctx sdk.Context, key string) any

func readSettingBool(ctx sdk.Context, key string, fallback bool) bool {
	if Setting == nil {
		return fallback
	}
	if v, ok := Setting(ctx, key).(bool); ok {
		return v
	}
	return fallback
}

func readSettingFloat(ctx sdk.Context, key string, fallback float64) float64 {
	if Setting == nil {
		return fallback
	}
	switch v := Setting(ctx, key).(type) {
	case float64:
		if !math.IsNaN(v) && !math.IsInf(v, 0) {
			return v
		}
	case int:
		return float64(v)
	case int64:
		return float64(v)
	}
	return fallback
}

func effectiveReadDefaultLimit(ctx sdk.Context) int {
	fallback := readDefaultLimit
	if raw := readSettingFloat(ctx, "read.defaultLimit", -1); raw > 0 {
		n := int(math.Floor(raw))
		if n < 1 {
			n = 1
		}
		if n > DefaultMaxLines {
			n = DefaultMaxLines
		}
		return n
	}
	return fallback
}

func effectiveOutputMaxColumns(ctx sdk.Context) int {
	if raw := readSettingFloat(ctx, "tools.outputMaxColumns", -1); raw >= 0 {
		return int(math.Floor(raw))
	}
	return readMaxColumns
}

func effectiveSpillThreshold(ctx sdk.Context) int {
	if rawKB := readSettingFloat(ctx, "tools.artifactSpillThreshold", -1); rawKB > 0 {
		if bytes := int(math.Floor(rawKB * 1024)); bytes > 0 {
			return bytes
		}
	}
	return DefaultSpillThreshold
}

// Register registers omp's read, write, and edit tools on e.
func Register(e *sdk.Extension) {
	hashline.RegisterLifecycle()
	e.OnSessionShutdown(func(ctx sdk.Context, _ map[string]any) (any, error) {
		if sid, err := ctx.GetSessionID(); err == nil && sid != "" {
			lifecycle.End(sid)
		}
		return nil, nil
	})
	readDef := schemaorder.Apply(sdk.ToolDefinition{
		Name:        "read",
		Label:       "Read",
		Description: strings.TrimSpace(readDescription),
		Parameters: sdk.Schema{
			"type": "object",
			"properties": map[string]any{
				"path": map[string]any{
					"type":        "string",
					"description": "Local path, internal URI, or URL; selectors inline.",
				},
			},
			"required":             []string{"path"},
			"additionalProperties": false,
		},
		Execute: func(ctx sdk.Context, params map[string]any) (any, error) {
			path, ok := params["path"].(string)
			if !ok {
				return nil, fmt.Errorf("invalid read arguments: path must be a string")
			}
			return executeReadWithCtx(ctx, hashline.ForSession(ctx), ctx.Cwd(), path)
		},
	})
	e.RegisterTool(intent.Tool(readDef))

	writeDef := schemaorder.Apply(sdk.ToolDefinition{
		Name:          "write",
		Label:         "Write",
		Description:   strings.TrimSpace(writeDescription),
		ExecutionMode: "sequential",
		Parameters: sdk.Schema{
			"type": "object",
			"properties": map[string]any{
				"path": map[string]any{
					"type": "string",
				},
				"content": map[string]any{
					"type": "string",
				},
			},
			"required":             []string{"path", "content"},
			"additionalProperties": false,
		},
		Execute: func(ctx sdk.Context, params map[string]any) (any, error) {
			path, ok := params["path"].(string)
			if !ok {
				return nil, fmt.Errorf("invalid write arguments: path must be a string")
			}
			var content *string
			if raw, exists := params["content"]; exists && raw != nil {
				s, ok := raw.(string)
				if !ok {
					return nil, fmt.Errorf("invalid write arguments: content must be a string")
				}
				content = &s
			}
			return executeWrite(ctx, hashline.ForSession(ctx), ctx.Cwd(), path, content)
		},
	})
	e.RegisterTool(intent.Tool(writeDef))

	editDef := schemaorder.Apply(sdk.ToolDefinition{
		Name:          "edit",
		Label:         "Edit",
		Description:   strings.TrimSpace(editDescription),
		ExecutionMode: "sequential",
		Parameters: sdk.Schema{
			"type": "object",
			"properties": map[string]any{
				"input": map[string]any{
					"type": "string",
				},
			},
			"required":             []string{"input"},
			"additionalProperties": false,
		},
		Execute: func(ctx sdk.Context, params map[string]any) (any, error) {
			input, ok := params["input"].(string)
			if !ok {
				return nil, fmt.Errorf("invalid edit arguments: input must be a string")
			}
			return executeEdit(ctx, hashline.ForSession(ctx), ctx.Cwd(), input)
		},
	})
	e.RegisterTool(intent.Tool(editDef))
	intent.RegisterSync(e, readDef, writeDef, editDef)
}
